import pytest

def shipping_fee(weight_kg, zone='normal'):
    """Calculate shipping fee based on weight and zone.

    Rules:
    - ≤1kg: 8 yuan base
    - 1-5kg: 8 + (weight - 1) * 3 yuan
    - >5kg: 8 + 4*3 + (weight - 5) * 2, capped at 45 yuan
    - zone='remote': multiply by 1.5
    """
    if weight_kg <= 1:
        fee = 8
    elif weight_kg <= 5:
        fee = 8 + (weight_kg - 1) * 3
    else:
        fee = min(8 + 4 * 3 + (weight_kg - 5) * 2, 45)

    if zone == 'remote':
        fee *= 1.5

    return fee


class TestShippingFee:
    # Required cases
    def test_0_5kg_normal_zone(self):
        assert shipping_fee(0.5) == 8

    def test_3kg_normal_zone(self):
        assert shipping_fee(3) == 8 + (3 - 1) * 3  # 14

    def test_8kg_normal_zone(self):
        assert shipping_fee(8) == 8 + 4 * 3 + (8 - 5) * 2  # 26

    def test_8kg_remote_zone(self):
        assert shipping_fee(8, 'remote') == 26 * 1.5  # 39

    # Boundary cases
    def test_1kg_boundary(self):
        assert shipping_fee(1) == 8

    def test_5kg_boundary(self):
        assert shipping_fee(5) == 8 + (5 - 1) * 3  # 20

    def test_5kg_01_exceeds_boundary(self):
        assert shipping_fee(5.01) == 8 + 4 * 3 + (5.01 - 5) * 2  # 20.02

    # Cap enforcement
    def test_weight_exceeds_cap(self):
        # >5kg: 8 + 12 + (weight-5)*2; at 22.5kg: 8+12+35 = 55 → capped at 45
        assert shipping_fee(22.5) == 45

    def test_remote_cap_applies_before_multiplier(self):
        # 22.5kg: 45 * 1.5 = 67.5
        assert shipping_fee(22.5, 'remote') == 45 * 1.5

    def test_1kg_remote(self):
        assert shipping_fee(1, 'remote') == 8 * 1.5  # 12
```

**Run with:** `pytest test_shipping_fee.py -v`
